'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { Worker } = require('node:worker_threads');
const { lock, unlock } = require('./lock.js');

const WORKERS = 4;
const ITERATIONS = 100_000;

// Shared memory layout:
//   cell 0 -> mutex state (managed by lock/unlock)
//   cell 1 -> plain (non-atomic) shared counter
//   cell 2..(2+N-1) -> per-worker completion counters (for fairness check)
const LOCK_IDX = 0;
const COUNTER_IDX = 1;
const DONE_BASE = 2;

function workerSource(withLock) {
  return `
  'use strict';
  const { workerData } = require('node:worker_threads');
  const { lock, unlock } = require(${JSON.stringify(__filename.replace(/\\.test\\.js$/, '.js').replace('mutex.test.js', 'lock.js'))});
  const { arr, idx, useLock } = workerData;
  const me = ${'${}'}; // placeholder
  `;
}

// Worker body as plain string (eval:true) so everything lives in this file.
function makeWorkerSource(useLock) {
  return `
  'use strict';
  const { parentPort, workerData } = require('node:worker_threads');
  const { lock, unlock } = require(${JSON.stringify(require.resolve('./lock.js'))});
  const { arr, lockIdx, counterIdx, doneIdx, iterations, useLock } = workerData;
  for (let i = 0; i < iterations; i++) {
    if (useLock) {
      lock(arr, lockIdx);
      arr[counterIdx] = arr[counterIdx] + 1;   // non-atomic read-modify-write
      unlock(arr, lockIdx);
    } else {
      arr[counterIdx] = arr[counterIdx] + 1;   // non-atomic read-modify-write
    }
    arr[doneIdx]++;                            // per-worker progress
  }
  parentPort.postMessage(arr[doneIdx]);        // report completed iterations
  `;
}

function runWorkers(useLock) {
  return new Promise((resolve, reject) => {
    const sab = new SharedArrayBuffer((DONE_BASE + WORKERS) * 4);
    const arr = new Int32Array(sab);
    let pending = WORKERS;
    const doneCounts = [];

    for (let w = 0; w < WORKERS; w++) {
      const worker = new Worker(makeWorkerSource(useLock), {
        eval: true,
        workerData: {
          arr,
          lockIdx: LOCK_IDX,
          counterIdx: COUNTER_IDX,
          doneIdx: DONE_BASE + w,
          iterations: ITERATIONS,
          useLock,
        },
      });
      worker.on('message', (n) => doneCounts.push(n));
      worker.on('error', reject);
      worker.on('exit', () => {
        if (--pending === 0) resolve({ finalValue: arr[COUNTER_IDX], doneCounts });
      });
    }
  });
}

test('mutex provides mutual exclusion: exactly 400000 increments survive', async () => {
  const { finalValue, doneCounts } = await runWorkers(true);

  // Fairness smoke check: every worker ran its full iteration count.
  assert.strictEqual(doneCounts.length, WORKERS);
  for (const n of doneCounts) {
    assert.strictEqual(n, ITERATIONS, `each worker must complete all ${ITERATIONS} iterations`);
  }

  // Mutual exclusion proof: no update lost.
  assert.strictEqual(finalValue, WORKERS * ITERATIONS);
});

test('without the mutex, updates are lost (final value < 400000)', async () => {
  const { finalValue, doneCounts } = await runWorkers(false);

  // Workers still finish all their work...
  assert.strictEqual(doneCounts.length, WORKERS);
  for (const n of doneCounts) assert.strictEqual(n, ITERATIONS);

  // ...but the non-atomic increments race and some are lost. A value strictly
  // less than the total proves the critical section was violated.
  assert.ok(
    finalValue < WORKERS * ITERATIONS,
    `expected lost updates without the mutex, got ${finalValue}`
  );
});

// Sanity: exported functions exist and main thread cannot Atomics.wait.
test('lock/unlock API surface', async (t) => {
  await t.test('exports', () => {
    assert.strictEqual(typeof lock, 'function');
    assert.strictEqual(typeof unlock, 'function');
  });

  await t.test('main thread cannot Atomics.wait (documented constraint)', async () => {
    const sab = new SharedArrayBuffer(4);
    const arr = new Int32Array(sab);
    Atomics.store(arr, 0, 0);
    assert.throws(() => Atomics.wait(arr, 0, 0), Error);
  });
});

