'use strict';

// A mutex built on Atomics.compareExchange + Atomics.wait/Atomics.notify.
//
// NOTE: Atomics.wait() may only be used where blocking is allowed.
// The Node.js *main thread* cannot use it: unlike browsers (where it throws),
// on the Node main thread it silently blocks forever. Therefore lock()/unlock()
// are intended for use inside worker_threads Workers only.

const UNLOCKED = 0;
const LOCKED = 1;

/**
 * Acquire the mutex stored at `idx` in `int32arr` (an Int32Array over a
 * SharedArrayBuffer). Blocks the calling worker until acquired, using
 * Atomics.wait (futex) instead of busy-spinning while contended.
 */
function lock(int32arr, idx) {
  // Fast path: uncontended CAS.
  while (Atomics.compareExchange(int32arr, idx, UNLOCKED, LOCKED) !== UNLOCKED) {
    // Slow path: cell is taken. Sleep on it until unlock() notifies us.
    // Re-read before waiting; wait() returns immediately ("not-equal") if the
    // value changed between our load and the wait, which just re-loops.
    const v = Atomics.load(int32arr, idx);
    if (v === LOCKED) {
      const status = Atomics.wait(int32arr, idx, LOCKED);
      // "ok" -> woken by notify(); "not-equal" -> state changed first.
      // Either way, loop and retry the CAS. ("timed-out" impossible: no timeout.)
      void status;
    }
  }
}

/**
 * Release the mutex stored at `idx`. Must be called by the owner,
 * from inside a Worker (see note above).
 */
function unlock(int32arr, idx) {
  Atomics.store(int32arr, idx, UNLOCKED);
  // Wake one waiter (if any). Waking more than one is harmless but causes
  // thundering-herd retries; one is enough since we hand off a single lock.
  Atomics.notify(int32arr, idx, 1);
}

module.exports = { lock, unlock };

